arguments.content:
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name localhost;

    ssl_certificate /etc/ssl/certs/nginx-selfsigned.crt;
    ssl_certificate_key /etc/ssl/private/nginx-selfsigned.key;
    ssl_protocols TLSv1.2 TLSv1.3;

    location = /dev {
        return 301 /dev/;
    }

    location ^~ /dev/ {
        root /var/www/git-sites;
        index index.html;
        try_files $uri $uri/ =404;
    }

    location / {
        root /var/www/git-sites/main;
        index index.html;
        try_files $uri $uri/ =404;
    }
}

